#!/bin/bash
set -euo pipefail

# This script is called by Dune to build and copy Skia and its modules.
# It reads arguments from files generated by the OCaml configurator.

# Arguments passed from Dune via files
OS_NAME=$(cat os.txt)
ARCH_NAME=$(cat arch.txt)
LIB_EXT=$(cat lib_ext.txt)

# Environment variable to control shaping
SKIA_ENABLE_SHAPING="${SKIA_ENABLE_SHAPING:-}" # Default to empty string if not set

# --- Step 1: Prepare Ninja targets and copy lists ---
NINJA_TARGETS="skia modules/skottie modules/svg"
COPY_LIBS_BASE="libskia libsvg libskottie"

COPY_HEADERS_COMMANDS=() # Array to store header copy commands

if [[ "$SKIA_ENABLE_SHAPING" = "1" || "$SKIA_ENABLE_SHAPING" = "yes" ]]; then
  echo "SKIA_ENABLE_SHAPING is enabled. Including SkShaper."
  NINJA_TARGETS="$NINJA_TARGETS modules/skshaper modules/skparagraph"
  COPY_LIBS_BASE="$COPY_LIBS_BASE libskshaper libskparagraph"
else
  echo "SKIA_ENABLE_SHAPING is disabled. Excluding SkShaper."
fi

# --- Step 2: Build Skia using Ninja ---
echo "Running ninja with targets: $NINJA_TARGETS"
ninja -C skia/out/"$OS_NAME"/"$ARCH_NAME" $NINJA_TARGETS

# --- Step 3: Copy compiled libraries and headers to prefix/ ---
echo "Copying libraries to prefix/lib..."
mkdir -p prefix/lib

# Build the cp command string for libraries
LIBS_CP_COMMAND=""
for lib_name in $COPY_LIBS_BASE; do
  LIBS_CP_COMMAND+="cp skia/out/$OS_NAME/$ARCH_NAME/${lib_name}.$LIB_EXT prefix/lib/ && "
done
# Remove trailing " && " and execute
eval "${LIBS_CP_COMMAND% && }"

echo "Copying headers to prefix/include/..."
mkdir -p prefix/include/c
cp -r skia/include/c/* prefix/include/c

mkdir -p prefix/include/svg
cp -r skia/modules/svg/include/* prefix/include/svg

mkdir -p prefix/include/skottie
cp -r skia/modules/skottie/include/* prefix/include/skottie

# Conditional header copying for skshaper
if [[ "$SKIA_ENABLE_SHAPING" = "1" || "$SKIA_ENABLE_SHAPING" = "yes" ]]; then
  mkdir -p prefix/include/skshaper
  cp -r skia/modules/skshaper/include/* prefix/include/skshaper

  mkdir -p prefix/include/skparagraph
  cp -r skia/modules/skparagraph/include/* prefix/include/skparagraph
fi